let rows = [];

for (const item of $input.all()) {
  if (Array.isArray(item.json)) rows.push(...item.json);
  else if (Array.isArray(item.json?.data)) rows.push(...item.json.data);
  else rows.push(item.json);
}

rows = rows
  .filter(r => r && r.ticker)
  .map(r => ({
    json: {
      ticker: String(r.ticker).trim().toUpperCase(),
      company_name: r.company_name || null,
      ai_subsector: r.ai_subsector || null
    }
  }));

if (!rows.length) {
  throw new Error('No active tickers found in ai_stock_universe.');
}

return rows;

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

function getSgtDate() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Singapore',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());

  return `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;
}

let base = {};
try {
  base = $('Loop Over AI Stocks').first().json || {};
} catch (e) {}

let rows = [];
for (const item of $input.all()) {
  const j = item.json;

  if (Array.isArray(j)) rows.push(...j);
  else if (Array.isArray(j?.historical)) rows.push(...j.historical);
  else if (Array.isArray(j?.data)) rows.push(...j.data);
  else if (Array.isArray(j?.results)) rows.push(...j.results);
  else rows.push(j);
}

rows = rows
  .filter(r => r && (r.date || r.price_date || r.metric_date))
  .map(r => ({
    date: r.date || r.price_date || r.metric_date,
    close: toNum(r.close ?? r.adjClose ?? r.adj_close ?? r.price),
    volume: toNum(r.volume)
  }))
  .filter(r => r.date && r.close !== null)
  .sort((a, b) => String(b.date).localeCompare(String(a.date)));

const ticker = String(base.ticker || '').toUpperCase();

if (!ticker) {
  return [{
    json: {
      metric_date: getSgtDate(),
      ticker: null,
      error: 'Ticker could not be resolved from Loop Over AI Stocks.',
      rows_received: rows.length,
      source: 'fmp_historical_price_eod'
    }
  }];
}

if (rows.length < 2) {
  return [{
    json: {
      metric_date: getSgtDate(),
      ticker,
      company_name: base.company_name || null,
      ai_subsector: base.ai_subsector || null,
      error: `Insufficient FMP historical EOD data for ${ticker}`,
      rows_received: rows.length,
      source: 'fmp_historical_price_eod'
    }
  }];
}

const latest = rows[0];
const previous = rows[1];

const latestPrice = latest.close;
const previousClose = previous.close;
const volume = latest.volume;

let dayChange = null;
let dayChangePct = null;

if (latestPrice !== null && previousClose !== null && previousClose !== 0) {
  dayChange = latestPrice - previousClose;
  dayChangePct = (dayChange / previousClose) * 100;
}

const closes200 = rows.slice(0, 200).map(r => r.close).filter(v => v !== null);

let ma200 = null;
if (closes200.length >= 200) {
  ma200 = closes200.reduce((a, b) => a + b, 0) / closes200.length;
}

return [{
  json: {
    metric_date: getSgtDate(),
    ticker,
    company_name: base.company_name || null,
    ai_subsector: base.ai_subsector || null,
    latest_price: round2(latestPrice),
    previous_close: round2(previousClose),
    day_change: round2(dayChange),
    day_change_pct: round2(dayChangePct),
    volume,
    ma200: round2(ma200),
    momentum_score: null,
    valuation_proxy: null,
    composite_score: null,
    regime: null,
    quadrant: null,
    source: 'fmp_historical_price_eod'
  }
}];

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const metricDate = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;

return [{ json: { metric_date: metricDate } }];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

const avg = arr => {
  const nums = arr.map(toNum).filter(v => v !== null);
  if (!nums.length) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
};

const stddev = arr => {
  const nums = arr.map(toNum).filter(v => v !== null);
  if (nums.length < 2) return null;
  const mean = nums.reduce((a, b) => a + b, 0) / nums.length;
  const variance = nums.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / (nums.length - 1);
  return Math.sqrt(variance);
};

let rows = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) rows.push(...item.json);
  else if (Array.isArray(item.json?.data)) rows.push(...item.json.data);
  else rows.push(item.json);
}

rows = rows.filter(r => r && r.metric_date && r.ai_subsector);

const groups = {};
for (const row of rows) {
  const key = `${row.metric_date}||${row.ai_subsector}`;
  if (!groups[key]) groups[key] = [];
  groups[key].push(row);
}

const output = [];

for (const [key, group] of Object.entries(groups)) {
  const [metricDate, aiSubsector] = key.split('||');

  const valuationValues = group.map(r => toNum(r.valuation_proxy)).filter(v => v !== null);
  const avgValuation = avg(group.map(r => r.valuation_proxy));
  const avgMomentum = avg(group.map(r => r.momentum_score));
  const avgComposite = avg(group.map(r => r.composite_score));
  const avgDayChangePct = avg(group.map(r => r.day_change_pct));

  let valuationRegime = 'Fair Value';
  if (avgValuation !== null) {
    if (avgValuation >= 25) valuationRegime = 'Highly Overvalued';
    else if (avgValuation >= 10) valuationRegime = 'Moderately Overvalued';
    else if (avgValuation <= -10) valuationRegime = 'Undervalued';
  }

  let subsectorRegime = 'Neutral';
  if (avgComposite !== null) {
    if (avgComposite >= 60) subsectorRegime = 'Strong';
    else if (avgComposite <= 40) subsectorRegime = 'Weak';
  }

  output.push({
    json: {
      metric_date: metricDate,
      ai_subsector: aiSubsector,
      stock_count: group.length,
      avg_valuation_proxy: round2(avgValuation),
      min_valuation_proxy: valuationValues.length ? round2(Math.min(...valuationValues)) : null,
      max_valuation_proxy: valuationValues.length ? round2(Math.max(...valuationValues)) : null,
      valuation_dispersion: round2(stddev(group.map(r => r.valuation_proxy))),
      avg_momentum_score: round2(avgMomentum),
      avg_composite_score: round2(avgComposite),
      avg_day_change_pct: round2(avgDayChangePct),
      valuation_regime: valuationRegime,
      subsector_regime: subsectorRegime
    }
  });
}

return output;
